export function evaluate({ inputs, time }) {
  const Ta = sdk.clamp(Number(inputs.room), 0, 30);
  const T0 = 90, k = 0.05, tMax = 60, dur = 20;
  const tm = sdk.clamp(time / dur * tMax, 0, tMax);
  const X0 = 100, X1 = 610, Y0 = 460, Y1 = 60;
  const xs = sdk.linear([0, tMax], [X0, X1]);
  const ys = sdk.linear([0, 100], [Y0, Y1]);
  const temp = (t, a) => a + (T0 - a) * Math.exp(-k * t);
  const obj = [];
  obj.push(sdk.line('xaxis', X0, Y0, X1, Y0));
  obj.push(sdk.line('yaxis', X0, Y0, X0, Y1));
  for (let m = 0; m <= 60; m += 10) obj.push(sdk.text('xt' + m, xs(m), Y0 + 22, String(m), { align: 'middle' }));
  for (let c = 0; c <= 100; c += 20) obj.push(sdk.text('yt' + c, X0 - 16, ys(c) + 5, String(c), { align: 'middle' }));
  obj.push(sdk.text('xlab', (X0 + X1) / 2, Y0 + 50, 'Time (minutes)', { align: 'middle' }));
  obj.push(sdk.text('ylab', X0 - 60, Y1 - 20, 'Temperature (°C)'));
  obj.push(sdk.line('roomline', X0, ys(Ta), X1, ys(Ta), { role: 'input', opacity: 0.8 }));
  obj.push(sdk.text('roomlab', X0 + 10, ys(Ta) - 8, 'Room ' + sdk.format(Ta, 0) + ' °C', { role: 'input' }));
  if (Math.abs(Ta - 20) > 0.5) {
    const refPts = [];
    for (let i = 0; i <= 60; i++) { const t = i / 60 * tMax; refPts.push([xs(t), ys(temp(t, 20))]); }
    obj.push(sdk.polyline('ref', refPts, { role: 'neutral', opacity: 0.35 }));
  }
  const full = [];
  for (let i = 0; i <= 120; i++) { const t = i / 120 * tMax; full.push([xs(t), ys(temp(t, Ta))]); }
  obj.push(sdk.polyline('future', full, { role: 'prediction', opacity: 0.3 }));
  const te = Math.max(tm, 0.01);
  const done = [];
  for (let i = 0; i <= 60; i++) { const t = i / 60 * te; done.push([xs(t), ys(temp(t, Ta))]); }
  obj.push(sdk.polyline('trace', done, { role: 'output' }));
  const Tc = temp(tm, Ta);
  const cx = xs(tm), cy = ys(Tc);
  obj.push(sdk.circle('dot', cx, cy, 14, { role: 'output' }));
  if (cx < X0 + 50) {
    obj.push(sdk.text('dotlab', cx + 14, cy - 12, sdk.format(Tc, 1) + ' °C', { align: 'start', role: 'output' }));
  } else {
    obj.push(sdk.text('dotlab', cx, cy - 16, sdk.format(Tc, 1) + ' °C', { align: 'middle', role: 'output' }));
  }
  const PX = 650;
  obj.push(sdk.text('s1', PX, 80, "Newton's law of cooling"));
  obj.push(sdk.math('s2', PX, 120, 'T(t)=T_a+(T_0-T_a)\\,e^{-kt}'));
  obj.push(sdk.text('s2b', PX, 150, 'T_a = room temperature', { opacity: 0.8 }));
  obj.push(sdk.text('s3', PX, 180, 'Start 90 °C, k = 0.05 per min'));
  obj.push(sdk.text('s4', PX, 216, 'The bigger the gap to the'));
  obj.push(sdk.text('s5', PX, 238, 'room, the faster it cools.'));
  obj.push(sdk.text('s6', PX, 274, 'The gap halves every'));
  obj.push(sdk.text('s7', PX, 296, 'about 14 minutes.'));
  obj.push(sdk.text('s8', PX, 332, 'Colder room: faster drop,'));
  obj.push(sdk.text('s9', PX, 354, 'settles at a lower temp.'));
  obj.push(sdk.text('s10', PX, 396, 'Faint grey curve:', { opacity: 0.7 }));
  obj.push(sdk.text('s11', PX, 418, '20 °C room, to compare.', { opacity: 0.7 }));
  const gap = Tc - Ta, rate = k * gap;
  return {
    frame: { width: 960, height: 540, objects: obj, readouts: [
      { id: 'coffee', value: Tc }, { id: 'minutes', value: tm }, { id: 'gap', value: gap }, { id: 'rate', value: rate }] },
    quantities: { coffee: Tc, minutes: tm, gap: gap, rate: rate, room_temp: Ta }
  };
}
